import {notify} from './action-feedback.js?v=1';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const feedbackCategories={NOT_RELEVANT:'Không phù hợp / không cần làm',UNCLEAR:'Khó hiểu, cần hướng dẫn thêm',CONTENT:'Nội dung chưa đúng',DEADLINE:'Thời hạn chưa đúng',TECHNICAL:'Lỗi thao tác',OTHER:'Góp ý khác'};
export const feedbackStatuses={OPEN:'Mới gửi',IN_REVIEW:'Đang xử lý',RESOLVED:'Đã xử lý',DECLINED:'Không cần điều chỉnh'};
let h,key='',data=null,loading=false,busy=false,error='',page=0,status='all',category='all',query='',detail=null,composer=null,pendingId=null,reply='',replyStatus='IN_REVIEW',replyId='';
const drafts=new Map();
const reviewer=()=>Boolean(h?.account()?.user.platformReviewer);
const path=()=>reviewer()?'/admin/feedback':'/companies/'+h.company()?.id+'/feedback';
const itemPath=id=>(reviewer()?'/admin':'')+'/feedback/'+id;
const date=x=>new Date(x).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'});
const pill=s=>`<span class="feedback-status feedback-${esc(s.toLowerCase())}">${esc(feedbackStatuses[s]||s)}</span>`;
export function configureFeedback(hooks){h=hooks;}
export function invalidateFeedback(){key='';data=null;detail=null;composer=null;}
async function load(){const scope=[h.account()?.user.id,reviewer()?'admin':h.company()?.id].join(':');loading=true;error='';h.render();try{const q=new URLSearchParams({page:String(page),status,category,q:query});const result=await h.api(path()+'?'+q);if(scope!==[h.account()?.user.id,reviewer()?'admin':h.company()?.id].join(':'))return;data=result;if(page>0&&!data.items.length){page--;await load();}}catch(e){error=e.message;}finally{loading=false;h.render();}}
async function open(id){const scope=[h.account()?.user.id,reviewer()?'admin':h.company()?.id].join(':');const result=await h.api(itemPath(id));if(h.screen()!=='feedback'||scope!==[h.account()?.user.id,reviewer()?'admin':h.company()?.id].join(':'))return;detail=result;reply='';replyId=crypto.randomUUID();replyStatus=result.status==='OPEN'?'IN_REVIEW':result.status;h.render();}
export function mountFeedback(){if(!h||h.screen()!=='feedback'){key='';return;}if(!h.account()||!reviewer()&&!h.company())return;const next=[h.account().user.id,reviewer()?'admin':h.company().id].join(':');if(key!==next&&!loading){key=next;data=null;detail=null;page=0;status='all';category='all';query='';void load().then(async()=>{if(pendingId){const id=pendingId;pendingId=null;try{await open(id);}catch(e){error=e.message;h.render();}}});}}
export function openTaskFeedback(task){const company=h.company();if(!company||reviewer())return;const draftKey=h.account().user.id+':'+company.id+':'+(task?.id||'general');composer=drafts.get(draftKey)||{draftKey,userId:h.account().user.id,companyId:company.id,requestId:crypto.randomUUID(),taskId:task?.id,taskTitle:task?.title,category:task?'NOT_RELEVANT':'OTHER',body:''};drafts.set(draftKey,composer);error='';h.render();}
function list(){const counts=data.counts||{},total=Object.values(counts).reduce((a,b)=>a+b,0);return `<div class="tab-bar" role="tablist" aria-label="Trạng thái phản hồi">${[['all','Tất cả',total],...Object.entries(feedbackStatuses).map(([s,l])=>[s,l,counts[s]||0])].map(([s,l,n])=>`<button type="button" role="tab" data-feedback="status" data-status="${s}" aria-selected="${status===s}" class="${status===s?'active':''}" ${busy?'disabled':''}>${l}<span>${n}</span></button>`).join('')}</div><form id="feedback-filter" class="list-controls"><label class="search-control">${h.icon('search',17)}<input name="query" aria-label="Tìm phản hồi" placeholder="Tìm phản hồi…" value="${esc(query)}"></label><label>Loại vấn đề<select name="category"><option value="all">Tất cả</option>${Object.entries(feedbackCategories).map(([k,l])=>`<option value="${k}" ${category===k?'selected':''}>${l}</option>`).join('')}</select></label><button class="secondary-button">Áp dụng</button></form><div class="task-list feedback-list">${data.items.length?data.items.map(r=>`<article class="task-card feedback-card"><div class="task-card-main"><div class="task-card-overline"><span>${esc(feedbackCategories[r.category])}</span>${pill(r.status)}</div><h3>${esc(r.contextJson.taskTitle||r.title)}</h3><p>${esc(r.preview)}</p><div class="task-card-meta">${reviewer()?`<span>${esc(r.companyName)}</span>`:''}<span>${date(r.updatedAt)}</span><span>${r.messageCount} trao đổi</span></div></div><button type="button" class="task-open" data-feedback="open" data-id="${r.id}" aria-label="Mở phản hồi ${esc(r.contextJson.taskTitle||r.title)}">${h.icon('arrow',19)}</button></article>`).join(''):`<div class="empty-state">${h.icon('file',28)}<h2>${total?'Không có phản hồi phù hợp':'Chưa có phản hồi'}</h2><p>${reviewer()?'Phản hồi doanh nghiệp gửi sẽ xuất hiện tại đây.':'Bạn có thể báo vấn đề từ từng công việc hoặc gửi góp ý tại đây.'}</p></div>`}</div>${data.total?`<div class="change-pagination"><span>${page*10+1}–${Math.min((page+1)*10,data.total)} / ${data.total} phản hồi</span><div><button type="button" class="secondary-button" data-feedback="page" data-page="-1" ${page===0?'disabled':''}>Trước</button><span>Trang ${page+1}</span><button type="button" class="secondary-button" data-feedback="page" data-page="1" ${(page+1)*10>=data.total?'disabled':''}>Sau</button></div></div>`:''}`;}
function conversation(){const r=detail,c=r.contextJson;return `<div class="feedback-detail-head"><button type="button" class="text-action" data-feedback="back">${h.icon('arrow',16)} Danh sách phản hồi</button><button type="button" class="secondary-button" data-feedback="refresh">Cập nhật trao đổi</button>${pill(r.status)}</div><div class="feedback-layout"><section class="feedback-thread"><span class="rail-kicker">${esc(feedbackCategories[r.category])}</span><h2>${esc(c.taskTitle||r.title)}</h2><p class="field-hint">${esc(r.companyName)} · Gửi lúc ${date(r.createdAt)}</p>${r.olderCursor?'<button type="button" class="secondary-button" data-feedback="older">Xem trao đổi trước</button>':''}<ol class="feedback-messages">${r.messages.map(m=>`<li class="feedback-message ${m.actorRole==='REVIEWER'?'from-reviewer':''}"><div><strong>${m.actorRole==='REVIEWER'?'LIMI · ':''}${esc(m.authorName)}</strong><time datetime="${m.createdAt}">${date(m.createdAt)}</time></div><p>${esc(m.body)}</p>${m.actorRole==='REVIEWER'?pill(m.statusAfter):''}</li>`).join('')}</ol><form id="feedback-reply" class="product-form"><fieldset ${busy?'disabled':''}>${reviewer()?`<label>Trạng thái xử lý<select name="status">${Object.entries(feedbackStatuses).map(([k,l])=>`<option value="${k}" ${replyStatus===k?'selected':''}>${l}</option>`).join('')}</select></label>`:''}<label>${reviewer()?'Phản hồi cho doanh nghiệp':'Bổ sung thông tin'}<textarea name="body" required minlength="3" maxlength="4000" rows="4" placeholder="${reviewer()?'Nêu kết quả kiểm tra hoặc hướng xử lý…':'Thông tin bạn muốn bổ sung…'}">${esc(reply)}</textarea></label>${!reviewer()&&['RESOLVED','DECLINED'].includes(r.status)?'<p class="field-hint">Gửi thông tin bổ sung sẽ mở lại phản hồi này.</p>':''}<button class="primary-button">${reviewer()?'Gửi phản hồi và cập nhật':'Gửi bổ sung'}</button></fieldset></form></section><aside class="rail-panel feedback-context"><span class="rail-kicker">THÔNG TIN ĐI KÈM</span>${c.taskTitle?`<h3>Công việc được phản ánh</h3><p>${esc(c.taskTitle)}</p><dl><dt>Trạng thái khi gửi</dt><dd>${esc(({TODO:'Cần xử lý',DOING:'Đang thực hiện',DONE:'Đã hoàn thành',NOT_APPLICABLE:'Không áp dụng'})[c.taskStatus]||c.taskStatus)}</dd><dt>Hạn hiển thị khi gửi</dt><dd>${esc(c.dueDate||'Chưa có hạn')}</dd></dl>${reviewer()?'<button type="button" class="secondary-button" data-feedback="version">Kiểm tra checklist gốc</button>':'<button type="button" class="secondary-button" data-feedback="task">Xem công việc</button>'}`:'<h3>Góp ý về LIMI</h3><p>Phản hồi chung của doanh nghiệp.</p>'}<p class="field-hint">Phản hồi không tự đổi trạng thái công việc. Nội dung trao đổi được giữ để hai bên theo dõi.</p></aside></div>`;}
export function renderFeedback(){if(!h?.account())return '';if(!reviewer()&&!h.company())return `<section class="form-panel"><h1>Phản hồi</h1><p>Chọn doanh nghiệp để gửi và theo dõi phản hồi.</p><button type="button" class="secondary-button" data-nav="companies">Chọn doanh nghiệp</button></section>`;const head=h.pageTitle(reviewer()?'KHÔNG GIAN QUẢN LÍ':'ĐỒNG HÀNH CÙNG DOANH NGHIỆP',reviewer()?'Phản hồi doanh nghiệp':'Phản hồi của doanh nghiệp',reviewer()?'Tiếp nhận vấn đề, trao đổi và thông báo kết quả xử lý.':'Báo vấn đề bạn gặp và theo dõi phản hồi từ LIMI.',reviewer()?'<button type="button" class="secondary-button" data-feedback="refresh">Tải lại</button>':'<button type="button" class="primary-button" data-feedback="new">Gửi phản hồi</button>');return `<section class="feedback-workspace">${head}${error?`<p class="form-error" role="alert">${esc(error)}</p>`:''}${detail?conversation():!data?'<p role="status">Đang tải phản hồi…</p>':list()}</section>`;}
export function renderFeedbackOverlay(){if(!composer||composer.userId!==h.account()?.user.id||composer.companyId!==h.company()?.id||reviewer())return '';return `<div class="overlay-backdrop centered"><section class="feedback-compose" role="dialog" aria-modal="true" aria-labelledby="feedback-compose-title"><button type="button" class="close-button" data-feedback="cancel" aria-label="Đóng phản hồi">${h.icon('close',20)}</button><span class="rail-kicker">GỬI TỚI LIMI</span><h2 id="feedback-compose-title">Báo vấn đề bạn gặp</h2>${composer.taskTitle?`<p class="feedback-task-context">${esc(composer.taskTitle)}</p>`:''}<p class="field-hint">LIMI sẽ kiểm tra và phản hồi tại mục Phản hồi. Việc gửi báo cáo không tự đổi trạng thái công việc.</p>${error?`<p class="form-error" role="alert">${esc(error)}</p>`:''}<form id="feedback-create" class="product-form"><fieldset ${busy?'disabled':''}><label>Vấn đề bạn gặp<select name="category">${Object.entries(feedbackCategories).map(([k,l])=>`<option value="${k}" ${composer.category===k?'selected':''}>${l}</option>`).join('')}</select></label><label>Mô tả ngắn<textarea name="body" rows="4" minlength="3" maxlength="4000" required placeholder="Ví dụ: Công ty tôi không thực hiện hoạt động này, nhưng vẫn thấy công việc cần làm…">${esc(composer.body)}</textarea></label><div class="panel-actions"><button type="button" class="secondary-button" data-feedback="cancel">Để sau</button><button class="primary-button">${busy?'Đang gửi…':'Gửi phản hồi'}</button></div></fieldset></form></section></div>`;}
async function act(fn){if(busy)return;busy=true;error='';h.render();try{await fn();}catch(e){error=e.code==='REVISION_CONFLICT'?'Có trao đổi mới. Tải lại phản hồi trước khi gửi; nội dung bạn nhập vẫn được giữ.':e.message;}finally{busy=false;h.render();}}
document.addEventListener('input',e=>{if(e.target.closest('#feedback-create')&&composer)composer.body=e.target.closest('form').elements.body.value;if(e.target.closest('#feedback-reply'))reply=e.target.closest('form').elements.body.value;});
document.addEventListener('change',e=>{if(e.target.closest('#feedback-create')&&composer)composer.category=e.target.closest('form').elements.category.value;if(e.target.closest('#feedback-reply'))replyStatus=e.target.closest('form').elements.status?.value||replyStatus;});
document.addEventListener('click',e=>{const b=e.target.closest('[data-feedback]');if(!b||!h)return;const a=b.dataset.feedback;if(a==='cancel'){composer=null;error='';h.render();return;}if(a==='new'){openTaskFeedback();return;}if(busy)return;if(a==='back'){detail=null;error='';void load();return;}if(a==='version'){h.openVersion(detail.contextJson.basisVersionId);return;}if(a==='task'){h.openTask(detail.taskId);return;}void act(async()=>{if(a==='open')await open(b.dataset.id);if(a==='refresh'){if(detail){const draft=reply,draftStatus=replyStatus;await open(detail.id);reply=draft;replyStatus=draftStatus;}else await load();}if(a==='status'){status=b.dataset.status;page=0;await load();}if(a==='page'){page+=Number(b.dataset.page);await load();}if(a==='older'){const d=detail,older=await h.api(itemPath(d.id)+'?before='+d.olderCursor);if(detail===d){detail.messages=[...older.messages,...d.messages];detail.olderCursor=older.olderCursor;}}});});
document.addEventListener('submit',e=>{const form=e.target;if(!['feedback-create','feedback-reply','feedback-filter'].includes(form.id))return;e.preventDefault();if(busy)return;const fd=new FormData(form);if(form.id==='feedback-filter'){query=String(fd.get('query')||'');category=String(fd.get('category')||'all');page=0;void act(load);return;}if(form.id==='feedback-create'){const c=composer;c.body=String(fd.get('body')||'');c.category=String(fd.get('category'));void act(async()=>{const row=await h.api('/companies/'+c.companyId+'/feedback','POST',{requestId:c.requestId,...(c.taskId?{taskId:c.taskId}:{}),category:c.category,body:c.body});drafts.delete(c.draftKey);if(composer!==c||h.company()?.id!==c.companyId||h.account()?.user.id!==c.userId)return;composer=null;if(h.screen()==='feedback'){await load();await open(row.id);}else{pendingId=row.id;h.go('feedback');}notify('Đã gửi phản hồi. Bạn theo dõi kết quả tại đây.');});}else{reply=String(fd.get('body')||'');replyStatus=String(fd.get('status')||replyStatus);const d=detail;void act(async()=>{await h.api(itemPath(d.id)+'/messages','POST',{requestId:replyId,expectedRevision:d.revision,body:reply,...(reviewer()?{status:replyStatus}:{})});if(detail!==d||h.screen()!=='feedback')return;if(detail!==d||h.screen()!=='feedback')return;await open(d.id);data=null;await load();notify('Đã gửi trao đổi.');});}});
